import BlogPost from "../../layouts/BlogPost.astro";

const title = "NGINX rewriting rule for getting clean URL";
const description = "NGINX Rewriting for Clean WordPress Permalink Structure When deploying a dynamic application like WordPress behind a reverse proxy, managing the URL structure...";
