import BlogPost from "../../layouts/BlogPost.astro";

const title = "What is a More Effective Title Seperator for SEO purposes? | or -";
const description = "What is a More Effective Title Separator for SEO Purposes? The &lt;title&gt; tag is arguably one of the most critical on-page elements for Search Engine...";
